insert into kafaa_engine_cards (id, engine_surface, module, route, feature, title_en, title_ar, purpose_en, purpose_ar, owner_en, owner_ar, inputs_used, inputs_excluded, scoring_functions, weight_keys, output_en, output_ar, oversight_en, oversight_ar, limitations_en, limitations_ar, opt_out, version, last_changed_at, last_change_id, sources, sort, kernel_surface, ranks, fairness_metric, fairness_none) values
('digest', 'match', 'Shell', '/my', 'F36', 'Weekly digest', 'الملخص الأسبوعي', 'Picks at most seven things that need me this week and orders them by urgency, with matched opportunities scored like the marketplace.', 'يختار سبعة بنود كحد أقصى تحتاجني هذا الأسبوع ويرتّبها حسب الإلحاح، مع فرص مطابقة تُحتسب درجتها كما في سوق الفرص.', 'Head of Talent and Careers (role card)', 'رئيس المواهب والمسارات المهنية (بطاقة دور)', '[{"key":"digest_sources","en":"What needs me this week from my own records: approvals I owe, expiring qualifications, refreshers, coach picks and matched opportunities","ar":"ما يحتاجني هذا الأسبوع من سجلاتي: الموافقات المطلوبة مني والمؤهلات التي توشك على الانتهاء والتنشيط واختيارات المدرّب والفرص المطابقة"},{"key":"person_skills","en":"My skill levels and how each is evidenced (qualifications, courses, assessments, validated check-ins)","ar":"مستويات مهاراتي وكيف ثبتت كل مهارة (المؤهلات والدورات والتقييمات وتقييمات المهارات المعتمدة)"},{"key":"opportunities","en":"Each opportunity: skills needed, skills gained, eligible job families","ar":"كل فرصة: المهارات المطلوبة والمهارات المكتسبة والعائلات الوظيفية المؤهلة"},{"key":"career_targets","en":"My shortlisted target roles (only if I set them)","ar":"الأدوار المستهدفة في قائمتي المختصرة (إن حدّدتها فقط)"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/shell/digest/rules.ts#gatherDigest','src/shell/digest/rules.ts#matchScore','src/shell/digest/rules.ts#composeDigest','sql:kafaa_dg_gather']::text[], array['skills','development','target']::text[], 'A short weekly list, each item with why it is there and a link; opportunity items carry their match reasons.', 'قائمة أسبوعية قصيرة، لكل بند سبب ظهوره ورابط؛ وتحمل بنود الفرص أسباب المطابقة.', 'I choose the frequency, quiet hours and muted kinds; nothing is sent during quiet hours and nothing is decided for me. It never decides anything on its own: a person reads the reasons and chooses.', 'أختار التكرار وساعات الهدوء والأنواع المكتومة؛ لا يُرسل شيء في ساعات الهدوء ولا يُقرَّر شيء نيابة عني. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Only items from records Kafa''a holds; approvals outside Kafa''a do not appear. Opportunities follow the marketplace engine weights.', 'تظهر البنود المستمدة من سجلات كفاءة فقط؛ ولا تظهر الموافقات خارجها. وتتبع الفرص أوزان محرك سوق الفرص.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 9, 'match', 'options', 'digest_suggested', null),
('dalil_career', 'recommend', 'M13', '/ask', 'F37', 'Dalil career mode', 'وضع المسار المهني في دليل', 'Answers career questions with my own readiness, gaps, courses and open opportunities, each answer card ranked with its reasons.', 'يجيب عن الأسئلة المهنية بجاهزيتي وفجواتي ودوراتي والفرص المفتوحة، وكل بطاقة إجابة مرتبة مع أسبابها.', 'Head of Talent and Careers (role card)', 'رئيس المواهب والمسارات المهنية (بطاقة دور)', '[{"key":"career_context","en":"When I ask Dalil a career question: my skills, targets, training and open applications (read for that answer only)","ar":"عندما أسأل دليل سؤالاً مهنياً: مهاراتي وأهدافي وتدريبي وطلباتي المفتوحة (تُقرأ لتلك الإجابة فقط)"},{"key":"person_skills","en":"My skill levels and how each is evidenced (qualifications, courses, assessments, validated check-ins)","ar":"مستويات مهاراتي وكيف ثبتت كل مهارة (المؤهلات والدورات والتقييمات وتقييمات المهارات المعتمدة)"},{"key":"role_competencies","en":"The competency levels each role requires (core, important, useful)","ar":"مستويات الكفاءة التي يتطلبها كل دور (أساسية، مهمة، مفيدة)"},{"key":"training_records","en":"Courses I completed or am enrolled in","ar":"الدورات التي أكملتها أو المسجّل فيها"},{"key":"opportunities","en":"Each opportunity: skills needed, skills gained, eligible job families","ar":"كل فرصة: المهارات المطلوبة والمهارات المكتسبة والعائلات الوظيفية المؤهلة"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m13/career/engine.ts#CareerEngine','src/modules/m13/career/context.ts#careerCtxFrom']::text[], array['core','important','useful']::text[], 'Answer cards (roles, gaps, courses, opportunities) with reasons and links; no free-text generation.', 'بطاقات إجابة (أدوار، فجوات، دورات، فرص) مع الأسباب والروابط؛ دون توليد نص حر.', 'Guidance only; a person can hand the conversation to HR with my consent. Moves are decided by managers and HR. It never decides anything on its own: a person reads the reasons and chooses.', 'إرشاد فقط؛ ويمكن تحويل المحادثة إلى الموارد البشرية بموافقتي. ويقرّر المديرون والموارد البشرية التنقلات. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Uses the same deterministic engines as the Navigator, Coach and marketplace; questions outside careers are answered by the public mode or refused.', 'يستخدم المحركات الحتمية نفسها في المستكشف والمدرّب وسوق الفرص؛ وتُجاب الأسئلة خارج المسار المهني بالوضع العام أو تُرفض.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 10, 'recommend', 'options', 'career_mode_used', null),
('dalil_answers', 'search', 'M13', '/ask', 'F14 · M13', 'Dalil answers (retrieval)', 'إجابات دليل (الاسترجاع)', 'Finds the published passages that answer a question and cites them; refuses security, medical and exam topics.', 'يجد المقاطع المنشورة التي تجيب عن السؤال ويستشهد بها؛ ويرفض موضوعات الأمن والطب والاختبارات.', 'AI governance lead (role card)', 'مسؤول حوكمة الذكاء الاصطناعي (بطاقة دور)', '[{"key":"corpus_docs","en":"Published Dalil corpus documents with their citations (public pages only in public mode)","ar":"وثائق مدوّنة دليل المنشورة مع استشهاداتها (الصفحات العامة فقط في الوضع العام)"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m13/dalil/engine.ts#RetrievalEngine','src/modules/m13/dalil/engine.ts#GuardedEngine','src/modules/m13/dalil/engine.ts#ModelGatewayEngine']::text[], array['title','k1','b']::text[], 'An answer assembled from cited passages, with the sources; the model gateway slot is disabled.', 'إجابة مجمّعة من مقاطع مستشهد بها مع المصادر؛ ومنفذ بوابة النماذج معطّل.', 'Corpus documents are published by editors; refusals follow the published refusal policy and are evaluated before release. It never decides anything on its own: a person reads the reasons and chooses.', 'ينشر المحررون وثائق المدوّنة؛ وتتبع حالات الرفض سياسة الرفض المنشورة وتُقيَّم قبل الإصدار. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Answers only from the corpus; anything not published is unknown to it. Public mode reads public pages only.', 'يجيب من المدوّنة فقط؛ وما لم يُنشر لا يعرفه. ويقرأ الوضع العام الصفحات العامة فقط.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 11, 'search', 'content', null, 'anonymous'),
('pathways', 'recommend', 'M19', '/my/pathways', 'FS17', 'Future-skill pathways', 'مسارات المهارات المستقبلية', 'Orders published pathways by the skill levels they would add for me and my targets, within a time envelope I can keep.', 'يرتّب المسارات المنشورة حسب مستويات المهارات التي تضيفها لي ولأهدافي، ضمن إطار زمني يمكنني الالتزام به.', 'Training Manager (role card)', 'مدير التدريب (بطاقة دور)', '[{"key":"pathways","en":"Published pathways: skill, level, steps, time envelope and weekly hours","ar":"المسارات المنشورة: المهارة والمستوى والخطوات والإطار الزمني والساعات الأسبوعية"},{"key":"person_skills","en":"My skill levels and how each is evidenced (qualifications, courses, assessments, validated check-ins)","ar":"مستويات مهاراتي وكيف ثبتت كل مهارة (المؤهلات والدورات والتقييمات وتقييمات المهارات المعتمدة)"},{"key":"career_targets","en":"My shortlisted target roles (only if I set them)","ar":"الأدوار المستهدفة في قائمتي المختصرة (إن حدّدتها فقط)"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m19/pathways.ts#rankPathways']::text[], '{}'::text[], 'Ranked pathways with the level gain, weekly hours and reasons; enrolment is my choice.', 'مسارات مرتبة مع مكسب المستوى والساعات الأسبوعية والأسباب؛ والتسجيل خياري.', 'Pathways are published by the training manager after the coverage checks; nothing enrols me automatically. It never decides anything on its own: a person reads the reasons and chooses.', 'ينشر مدير التدريب المسارات بعد فحوص التغطية؛ ولا يسجّلني شيء تلقائياً. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Only published pathways with steps in the catalogue; level gains are planned, not measured, until evidence is recorded.', 'المسارات المنشورة ذات الخطوات في الكتالوج فقط؛ ومكاسب المستوى مخطّطة لا مقيسة حتى تُسجَّل الأدلة.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 12, 'rules', 'content', 'pathway_enrolled', null),
('externals', 'recommend', 'M19', '/learn/external', 'FS18', 'Curated external catalogue', 'الكتالوج الخارجي المنتقى', 'Suggests up to four external resources that passed the outcome criteria, for the skills my ranked pathways target.', 'يقترح حتى أربعة موارد خارجية اجتازت معايير النتائج، للمهارات التي تستهدفها مساراتي المرتبة.', 'Training Manager (role card)', 'مدير التدريب (بطاقة دور)', '[{"key":"external_resources","en":"Published external resources: skills, hours, cost band, languages and the outcome criteria they met","ar":"الموارد الخارجية المنشورة: المهارات والساعات وفئة التكلفة واللغات ومعايير النتائج التي استوفتها"},{"key":"person_skills","en":"My skill levels and how each is evidenced (qualifications, courses, assessments, validated check-ins)","ar":"مستويات مهاراتي وكيف ثبتت كل مهارة (المؤهلات والدورات والتقييمات وتقييمات المهارات المعتمدة)"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m19/pathways.ts#rankExternals']::text[], '{}'::text[], 'A short list per pathway with cost band, hours and languages; completion is self-declared until verified.', 'قائمة قصيرة لكل مسار مع فئة التكلفة والساعات واللغات؛ والإكمال ذاتي التصريح حتى يُتحقق منه.', 'Resources are curated and published by the training manager against published criteria; nothing is bought automatically. It never decides anything on its own: a person reads the reasons and chooses.', 'ينتقي مدير التدريب الموارد وينشرها وفق معايير منشورة؛ ولا يُشترى شيء تلقائياً. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'External completions never become verified evidence on their own.', 'لا تصبح الإنجازات الخارجية أدلة موثّقة بمفردها.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 13, 'rules', 'content', 'external_completed', null),
('translator', 'recommend', 'M18', '/careers/translate', 'FS34', 'Transferable-skills translator', 'مترجم المهارات القابلة للنقل', 'Translates the skills and experience someone enters into the Barakah roles they cover best, with the gaps and a first course.', 'يترجم المهارات والخبرات التي يُدخلها الشخص إلى أدوار براكة الأكثر تغطية لها، مع الفجوات وأول دورة.', 'Talent outreach lead (role card)', 'مسؤول استقطاب المواهب (بطاقة دور)', '[{"key":"held_skills","en":"The skills and experience I enter (nothing is stored)","ar":"المهارات والخبرات التي أدخلها (لا يُحفظ شيء)"},{"key":"occupation_templates","en":"ESCO occupation templates and the published Barakah role requirements","ar":"قوالب المهن في ESCO ومتطلبات أدوار براكة المنشورة"},{"key":"role_competencies","en":"The competency levels each role requires (core, important, useful)","ar":"مستويات الكفاءة التي يتطلبها كل دور (أساسية، مهمة، مفيدة)"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m18/translate.ts#translate','src/modules/m18/translate.ts#coverageOf','src/modules/m18/CareersTranslatePage.tsx#rankTranslation']::text[], array['core','important','useful']::text[], 'Roles ordered by weighted coverage (the Navigator formula) with the reasons; nothing is stored.', 'أدوار مرتبة حسب التغطية المرجّحة (معادلة المستكشف) مع الأسباب؛ ولا يُحفظ شيء.', 'Exploration only; applications go through the published recruitment process. It never decides anything on its own: a person reads the reasons and chooses.', 'للاستكشاف فقط؛ وتمر الطلبات بإجراءات التوظيف المنشورة. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Public tool: it cannot see real records, so coverage reflects only what was entered. Security roles show the path only.', 'أداة عامة: لا ترى السجلات الفعلية، فتعكس التغطية ما أُدخل فقط. وتعرض أدوار الأمن المسار فقط.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 14, 'recommend', 'options', null, 'anonymous'),
('fitness', 'skills', 'M29', '/my/ai-fluency/check', 'FS10 · FS37', 'AI and digital fitness check and drills', 'فحص اللياقة الرقمية وتمارين الذكاء الاصطناعي', 'Chooses the next question by area and difficulty, scores the check and governed AI drills, and writes capped evidence.', 'يختار السؤال التالي حسب المجال والصعوبة، ويحتسب نتيجة الفحص وتمارين الذكاء الاصطناعي المحوكمة، ويسجّل أدلة بسقف محدد.', 'AI governance lead (role card)', 'مسؤول حوكمة الذكاء الاصطناعي (بطاقة دور)', '[{"key":"fitness_responses","en":"My answers in the check: correct or not, per area and difficulty","ar":"إجاباتي في الفحص: صحيحة أم لا، لكل مجال ومستوى صعوبة"},{"key":"drill_responses","en":"My drill answers: the flags I raised, my decision and rationale","ar":"إجاباتي في التمارين: التنبيهات التي رفعتها وقراري ومبرراته"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m29/fitness.ts#nextStep','src/modules/m29/fitness.ts#pickItem','src/modules/m29/fitness.ts#scoreAttempt','src/modules/m29/drills.ts#scoreDrill','sql:kafaa_fit_next','sql:kafaa_fit_pick','sql:kafaa_fit_score']::text[], '{}'::text[], 'Area levels, a band and the reasons; evidence never above level 2 and never a qualification.', 'مستويات المجالات وفئة وأسباب؛ ولا تتجاوز الأدلة المستوى 2 ولا تكون مؤهلاً أبداً.', 'Items are written and reviewed by the training manager; results are mine and appear to HR only as suppressed aggregates. It never decides anything on its own: a person reads the reasons and chooses.', 'يكتب مدير التدريب الأسئلة ويراجعها؛ والنتائج لي ولا تظهر للموارد البشرية إلا كمجاميع محجوبة. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'A short self-paced check, not an exam; quarterly retakes show the trend.', 'فحص قصير ذاتي الوتيرة لا اختبار؛ وتُظهر الإعادات الفصلية الاتجاه.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 15, 'assess', 'content', 'fitness_completed', null),
('future_gigs', 'match', 'M20', '/opportunities/future', 'FS27', 'Future-skills gigs', 'مهام المهارات المستقبلية', 'Orders future-skills gigs by the skill levels they would add for me, inside my approved time envelope.', 'يرتّب مهام المهارات المستقبلية حسب مستويات المهارات التي تضيفها لي، ضمن إطاري الزمني المعتمد.', 'Head of Talent and Careers (role card)', 'رئيس المواهب والمسارات المهنية (بطاقة دور)', '[{"key":"future_gigs","en":"Future-skills gigs: skills gained, time envelope and the line manager release","ar":"مهام المهارات المستقبلية: المهارات المكتسبة والإطار الزمني وموافقة المدير المباشر"},{"key":"person_skills","en":"My skill levels and how each is evidenced (qualifications, courses, assessments, validated check-ins)","ar":"مستويات مهاراتي وكيف ثبتت كل مهارة (المؤهلات والدورات والتقييمات وتقييمات المهارات المعتمدة)"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m20/futureGigs.ts#rankFutureGigs']::text[], '{}'::text[], 'Ranked gigs with the level gain and fit; applying needs my line manager''s release.', 'مهام مرتبة مع مكسب المستوى والملاءمة؛ ويتطلب التقديم موافقة مديري المباشر.', 'Posting managers select; the score never selects anyone. It never decides anything on its own: a person reads the reasons and chooses.', 'يختار المديرون الناشرون؛ ولا تختار الدرجة أحداً أبداً. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Gigs without skills gained show no level gain; the envelope caps hours, not ambition.', 'لا تُظهر المهام دون مهارات مكتسبة مكسب مستوى؛ ويحدّ الإطار الساعات لا الطموح.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 16, 'rules', 'options', 'gig_selected', null),
('smr_delta', 'skills', 'M31', '/my/next-gen', 'FS38', 'SMR delta overlay', 'طبقة فروق المفاعلات الصغيرة', 'Shows what would change in my role for each small modular reactor technology and how ready I am for the delta.', 'يعرض ما سيتغير في دوري لكل تقنية مفاعل وحدات صغيرة ومدى جاهزيتي للفرق.', 'Future workforce lead (role card)', 'مسؤول القوى العاملة المستقبلية (بطاقة دور)', '[{"key":"smr_deltas","en":"SMR delta rows per role and technology (public sources) and my skill levels","ar":"صفوف فروق المفاعلات الصغيرة لكل دور وتقنية (مصادر عامة) ومستويات مهاراتي"},{"key":"person_skills","en":"My skill levels and how each is evidenced (qualifications, courses, assessments, validated check-ins)","ar":"مستويات مهاراتي وكيف ثبتت كل مهارة (المؤهلات والدورات والتقييمات وتقييمات المهارات المعتمدة)"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m31/nextgen.ts#deltaFor','src/modules/m31/nextgen.ts#readinessOf']::text[], '{}'::text[], 'Per technology: change size, what stays, the skills to build and my readiness; no deployment decision implied.', 'لكل تقنية: حجم التغيير وما يبقى والمهارات المطلوب بناؤها وجاهزيتي؛ دون أي قرار نشر ضمني.', 'Delta rows come from public sources and are published by the future workforce lead. It never decides anything on its own: a person reads the reasons and chooses.', 'تأتي صفوف الفروق من مصادر عامة وينشرها مسؤول القوى العاملة المستقبلية. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'A planning lens with no headcount or site. Transform-surface weights are defaults only and cannot be stored.', 'عدسة تخطيط دون أعداد موظفين أو مواقع. وأوزان سطح التحول افتراضية فقط ولا يمكن حفظها.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 17, 'transform', 'options', null, 'no_outcome'),
('twin_drills', 'skills', 'M31', '/my/twin-drills', 'FS40', 'Digital-twin diagnosis drills', 'تمارين التشخيص بالتوأم الرقمي', 'Scores my diagnosis of a simulated twin anomaly against the rubric and lists the drills that evidence a skill.', 'يقيّم تشخيصي لشذوذ توأم رقمي محاكى وفق معيار التصحيح ويعرض التمارين التي تثبت مهارة ما.', 'Nuclear training academy lead (role card)', 'مسؤول أكاديمية التدريب النووي (بطاقة دور)', '[{"key":"twin_submissions","en":"My twin drill submissions: checks, diagnosis, action and rationale","ar":"إجاباتي في تمارين التوأم الرقمي: الفحوص والتشخيص والإجراء والمبرر"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m31/twin.ts#scoreTwinDrill','src/modules/m31/twin.ts#twinDrillsFor']::text[], '{}'::text[], 'Points per rubric line, a pass mark with critical checks and capped evidence (SIMULATED data).', 'نقاط لكل بند في المعيار وعلامة نجاح مع فحوص حرجة وأدلة بسقف محدد (بيانات محاكاة).', 'Rubrics and keys are written by instructors; the drill never connects to the plant. It never decides anything on its own: a person reads the reasons and chooses.', 'يكتب المدربون المعايير والمفاتيح؛ ولا يتصل التمرين بالمحطة أبداً. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Synthetic scenarios; assess-surface weights are defaults only and cannot be stored.', 'سيناريوهات اصطناعية؛ وأوزان سطح التقييم افتراضية فقط ولا يمكن حفظها.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 18, 'assess', 'content', 'twin_passed', null),
('role_2030', 'skills', 'M30', '/my/role-2030', 'FS11 · FS12', 'My role in 2030', 'دوري في 2030', 'Maps how each task of my role may change with AI by 2030 and my readiness for the 2030 profile.', 'يرسم كيف قد تتغير كل مهمة في دوري بالذكاء الاصطناعي بحلول 2030 وجاهزيتي لملف 2030.', 'Future workforce lead (role card)', 'مسؤول القوى العاملة المستقبلية (بطاقة دور)', '[{"key":"role_profiles","en":"Role profiles now, in 2030 and 2035, and task exposure on the OECD AI capability scale","ar":"ملفات الأدوار اليوم وفي 2030 و2035، وتعرّض المهام وفق مقياس قدرات الذكاء الاصطناعي لمنظمة التعاون الاقتصادي والتنمية"},{"key":"person_skills","en":"My skill levels and how each is evidenced (qualifications, courses, assessments, validated check-ins)","ar":"مستويات مهاراتي وكيف ثبتت كل مهارة (المؤهلات والدورات والتقييمات وتقييمات المهارات المعتمدة)"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m30/transform.ts#transformRole','src/modules/m30/transform.ts#readinessFor','src/domain/engines/future.ts#taskExposure']::text[], '{}'::text[], 'Task exposure (augment, automate, stay) with reasons and my readiness per horizon.', 'تعرّض المهام (تعزيز، أتمتة، بقاء) مع الأسباب وجاهزيتي لكل أفق.', 'Profiles are planning assumptions published by the training manager and HR director; no role change is implied. It never decides anything on its own: a person reads the reasons and chooses.', 'الملفات افتراضات تخطيط ينشرها مدير التدريب ومدير الموارد البشرية؛ ولا يُفهم منها أي تغيير في الدور. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Exposure follows the published capability scale; transform-surface weights are defaults only.', 'يتبع التعرّض مقياس القدرات المنشور؛ وأوزان سطح التحول افتراضية فقط.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 19, 'transform', 'content', null, 'no_outcome'),
('adaptive', 'skills', 'M05', '/my/assessments/adaptive', 'FS21', 'Adaptive future-skills assessments', 'تقييمات المهارات المستقبلية التكيفية', 'Picks the next calibrated item from my answers so far and stops when the estimate is stable.', 'يختار السؤال المعايَر التالي من إجاباتي حتى الآن ويتوقف حين يستقر التقدير.', 'Nuclear training academy lead (role card)', 'مسؤول أكاديمية التدريب النووي (بطاقة دور)', '[{"key":"adaptive_items","en":"Calibrated item difficulty and my answers so far","ar":"صعوبة الأسئلة المعايَرة وإجاباتي حتى الآن"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/domain/engines/future.ts#nextItem','src/modules/m05/adaptive.ts#scoreAdaptive']::text[], '{}'::text[], 'An estimate, whether it meets the cut level, and capped evidence; safety-related banks never gate a qualification.', 'تقدير، وهل يبلغ مستوى القطع، وأدلة بسقف محدد؛ ولا تشترط بنوك السلامة أي مؤهل.', 'Banks and items are calibrated and reviewed by the academy; integrity flags go to a person. It never decides anything on its own: a person reads the reasons and chooses.', 'تعاير الأكاديمية البنوك والأسئلة وتراجعها؛ وتُحال إشارات النزاهة إلى شخص. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Item difficulty comes from synthetic calibration; assess-surface weights are defaults only.', 'تأتي صعوبة الأسئلة من معايرة اصطناعية؛ وأوزان سطح التقييم افتراضية فقط.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 20, 'assess', 'content', 'adaptive_completed', null),
('instructors', 'match', 'M02', '/training/instructors', 'F31', 'Instructor and SME candidates', 'المرشحون للتدريب والخبرة', 'Suggests colleagues who could become instructors or SMEs for a discipline, strongest evidence first.', 'يقترح زملاء يمكن أن يصبحوا مدربين أو خبراء في تخصص، بدءاً بأقوى الأدلة.', 'Training Manager (role card)', 'مدير التدريب (بطاقة دور)', '[{"key":"instructor_candidates","en":"Instructor and SME candidates: discipline, qualifications, observations and motivation","ar":"المرشحون للتدريب والخبرة: التخصص والمؤهلات والملاحظات والدافعية"},{"key":"person_skills","en":"My skill levels and how each is evidenced (qualifications, courses, assessments, validated check-ins)","ar":"مستويات مهاراتي وكيف ثبتت كل مهارة (المؤهلات والدورات والتقييمات وتقييمات المهارات المعتمدة)"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m02/instructorMatch.ts#rankSmeCandidates']::text[], array['skills','development','target']::text[], 'A candidate list with reasons; nominations are made by managers and the training manager.', 'قائمة مرشحين مع الأسباب؛ ويرشّح المديرون ومدير التدريب.', 'Every nomination is accepted by the person and qualified through observations; the list nominates no one. It never decides anything on its own: a person reads the reasons and chooses.', 'يقبل الشخص كل ترشيح ويتأهل عبر الملاحظات؛ ولا ترشّح القائمة أحداً. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Only evidence held in Kafa''a counts; teaching quality shows only after observations.', 'تُحتسب الأدلة الموجودة في كفاءة فقط؛ ولا تظهر جودة التدريس إلا بعد الملاحظات.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 21, 'match', 'people', 'instructor_nominated', null),
('reserve', 'match', 'M20', '/opportunities/reserve', 'F23', 'Alumni and expert reserve matching', 'مطابقة احتياطي الخريجين والخبراء', 'Matches opted-in alumni and experts to short engagements by the skills needed and their availability.', 'يطابق الخريجين والخبراء الذين اختاروا المشاركة مع ارتباطات قصيرة حسب المهارات المطلوبة وتوفرهم.', 'HR authority, CHCO office (role card)', 'سلطة الموارد البشرية، مكتب الرئيس التنفيذي لرأس المال البشري (بطاقة دور)', '[{"key":"reserve_members","en":"Alumni and experts who opted in: skills and availability window","ar":"الخريجون والخبراء الذين اختاروا المشاركة: المهارات وفترة التوفر"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m20/reserveMatch.ts#rankRequestsForMember','src/modules/m20/reserveMatch.ts#rankMembersForRequest']::text[], array['skills','development','target']::text[], 'Ranked requests for a member and ranked members for a request, with reasons.', 'طلبات مرتبة للعضو وأعضاء مرتبون للطلب، مع الأسباب.', 'HR reviews every engagement; members choose to take part and can withdraw at any time. It never decides anything on its own: a person reads the reasons and chooses.', 'تراجع الموارد البشرية كل ارتباط؛ ويختار الأعضاء المشاركة ويمكنهم الانسحاب في أي وقت. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Covers alumni who opted in, not current staff, so it is outside the staff fairness population.', 'يشمل الخريجين الذين اختاروا المشاركة لا الموظفين الحاليين، فهو خارج فئة الإنصاف للموظفين.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 22, 'match', 'people', null, 'non_staff'),
('simulator', 'recommend', 'M04', '/training/simulator', 'F28', 'Simulator scenario suggestions', 'اقتراحات سيناريوهات المحاكي', 'Suggests scenarios that cover the objectives a training cycle still misses.', 'يقترح سيناريوهات تغطي الأهداف التي لم تغطها دورة التدريب بعد.', 'Nuclear training academy lead (role card)', 'مسؤول أكاديمية التدريب النووي (بطاقة دور)', '[{"key":"sim_scenarios","en":"Simulator scenarios: objectives, competencies, last run and coverage of the cycle","ar":"سيناريوهات المحاكي: الأهداف والكفاءات وآخر تشغيل وتغطية الدورة"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m04/scenarios.ts#suggestScenarios']::text[], array['core','important','useful']::text[], 'Ranked scenarios with the objectives each would cover; the planner chooses.', 'سيناريوهات مرتبة مع الأهداف التي يغطيها كل منها؛ ويختار المخطط.', 'Cycles are approved maker-checker by the simulator lead and training manager. It never decides anything on its own: a person reads the reasons and chooses.', 'تُعتمد الدورات بمبدأ المُعِدّ والمُدقِّق من مسؤول المحاكي ومدير التدريب. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Ranks scenarios, not people.', 'يرتّب السيناريوهات لا الأشخاص.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 23, 'recommend', 'content', null, 'content'),
('knowledge_search', 'search', 'M24', '/knowledge', 'F20 · F21 · F30', 'Knowledge search', 'بحث المعرفة', 'Finds published knowledge assets, OE lessons, sessions and learning records for a query, best match first.', 'يجد أصول المعرفة المنشورة ودروس الخبرة التشغيلية والجلسات وسجلات التعلّم لاستعلام، الأفضل أولاً.', 'Knowledge management lead (role card)', 'مسؤول إدارة المعرفة (بطاقة دور)', '[{"key":"knowledge_index","en":"Published knowledge assets, OE lessons and course texts (BM25 index)","ar":"أصول المعرفة المنشورة ودروس الخبرة التشغيلية ونصوص الدورات (فهرس BM25)"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m24/kb.ts#searchKb','src/modules/m24/enrich.ts#bm25','src/modules/m24/enrich.ts#enrich']::text[], array['title','k1','b']::text[], 'Results with the matched terms; nothing is ranked about people.', 'نتائج مع المصطلحات المطابقة؛ ولا يُرتَّب شيء عن الأشخاص.', 'Assets are reviewed by an SME before publication. It never decides anything on its own: a person reads the reasons and chooses.', 'يراجع خبير الأصول قبل نشرها. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Keyword relevance (BM25) only; synonyms not in the text are missed.', 'صلة الكلمات المفتاحية فقط (BM25)؛ وتفوت المرادفات غير الواردة في النص.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 24, 'search', 'content', null, 'content'),
('klra', 'skills', 'M24', '/knowledge/klra', 'F20', 'Knowledge-loss risk assessment', 'تقييم مخاطر فقدان المعرفة', 'Proposes attrition and position factors for each critical position so the knowledge owner can rank where to capture first.', 'يقترح عوامل الاستنزاف والمنصب لكل منصب حرج ليرتّب مسؤول المعرفة أين يبدأ التوثيق.', 'Knowledge management lead (role card)', 'مسؤول إدارة المعرفة (بطاقة دور)', '[{"key":"klra_positions","en":"Position bands: retirement and contract-end bands, criticality and single points of failure (no ages or birth dates)","ar":"فئات المناصب: فئات التقاعد وانتهاء العقد والأهمية ونقاط الإخفاق المنفردة (دون أعمار أو تواريخ ميلاد)"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m24/klra.ts#proposeFactors','src/modules/m24/klra.ts#computeHeatmap']::text[], array['half_life_months']::text[], 'Proposed factors with reasons; the assessor confirms or adjusts every score.', 'عوامل مقترحة مع الأسباب؛ ويؤكد المقيّم كل درجة أو يعدّلها.', 'Scores are confirmed by a person; HR sees only the suppressed department heatmap. It never decides anything on its own: a person reads the reasons and chooses.', 'يؤكد شخص الدرجات؛ ولا ترى الموارد البشرية إلا خريطة الأقسام المحجوبة. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Uses bands, never ages or birth dates; synthetic HR feed.', 'يستخدم الفئات لا الأعمار أو تواريخ الميلاد أبداً؛ وتغذية موارد بشرية اصطناعية.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 25, 'skills', 'options', null, 'no_outcome'),
('leadership', 'recommend', 'M22', '/leadership', 'F16 · FS46 · FS47', 'Leadership programme suggestions', 'اقتراحات برامج القيادة', 'Orders leadership programmes and the behaviours to work on by my level, nominations and 360 results.', 'يرتّب برامج القيادة والسلوكيات التي أعمل عليها حسب مستواي وترشيحاتي ونتائج التقييم الشامل.', 'Head of Talent and Careers (role card)', 'رئيس المواهب والمسارات المهنية (بطاقة دور)', '[{"key":"leadership_programmes","en":"Leadership programmes, my nominations and completed modules, and 360 behaviour scores (form 2)","ar":"برامج القيادة وترشيحاتي والوحدات المكتملة ودرجات سلوكيات التقييم الشامل (النموذج 2)"},{"key":"person_skills","en":"My skill levels and how each is evidenced (qualifications, courses, assessments, validated check-ins)","ar":"مستويات مهاراتي وكيف ثبتت كل مهارة (المؤهلات والدورات والتقييمات وتقييمات المهارات المعتمدة)"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m22/domain.ts#rankProgrammes','src/modules/m22/future.ts#coachFocus']::text[], array['core','important','useful']::text[], 'Ranked programmes and focus behaviours with reasons; nominations are made by managers.', 'برامج مرتبة وسلوكيات تركيز مع الأسباب؛ ويرشّح المديرون.', 'Nominations are approved by HR; the pipeline feeds the F24 high-potential fairness metric. It never decides anything on its own: a person reads the reasons and chooses.', 'تعتمد الموارد البشرية الترشيحات؛ وتغذي القائمة مقياس الإنصاف للمواهب العالية في F24. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', '360 scores below the suppression threshold are not shown.', 'لا تُعرض درجات التقييم الشامل دون حد الحجب.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 26, 'recommend', 'options', 'hipo_pool', null),
('hu_situations', 'recommend', 'M08', '/my/safety-culture/ai', 'FS49', 'HU tools for a situation', 'أدوات الأداء البشري لموقف', 'Orders HU tool cards for a situation I pick (for example a confident AI summary), AI-era cards first.', 'يرتّب بطاقات أدوات الأداء البشري لموقف أختاره (مثل ملخص واثق من الذكاء الاصطناعي)، وبطاقات عصر الذكاء الاصطناعي أولاً.', 'Safety culture lead (role card)', 'مسؤول ثقافة السلامة (بطاقة دور)', '[{"key":"hu_tools","en":"HU tool cards with their situation cues, AI-era topic and linked drills or lessons","ar":"بطاقات أدوات الأداء البشري مع مؤشرات المواقف وموضوع عصر الذكاء الاصطناعي والتمارين أو الدروس المرتبطة"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m08/aiCulture.ts#matchSituation']::text[], '{}'::text[], 'Up to three cards with the cues they match and a linked drill or lesson.', 'حتى ثلاث بطاقات مع المؤشرات التي تطابقها وتمرين أو درس مرتبط.', 'Cards are written by the safety culture team; nothing is recorded about me. It never decides anything on its own: a person reads the reasons and chooses.', 'يكتب فريق ثقافة السلامة البطاقات؛ ولا يُسجَّل شيء عني. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Same answer for everyone: it ranks content, not people.', 'الإجابة نفسها للجميع: يرتّب المحتوى لا الأشخاص.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 27, 'rules', 'content', null, 'content'),
('student_journey', 'match', 'M06', '/pathways/journey', 'F34', 'Student journey suggestions', 'اقتراحات رحلة الطالب', 'Suggests job families and the next step of the route for students and applicants from their own answers.', 'يقترح عائلات وظيفية والخطوة التالية في المسار للطلاب والمتقدمين من إجاباتهم.', 'Talent outreach lead (role card)', 'مسؤول استقطاب المواهب (بطاقة دور)', '[{"key":"student_journey","en":"My journey answers: stage, interests and chosen route (students and applicants)","ar":"إجاباتي في الرحلة: المرحلة والاهتمامات والمسار المختار (الطلاب والمتقدمون)"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m06/journeyUi.tsx#familyRanked','src/modules/m06/journey.ts#suggestRoute']::text[], array['skills','development','target']::text[], 'Ranked families and a route suggestion with reasons; applications follow the published process.', 'عائلات مرتبة واقتراح مسار مع الأسباب؛ وتتبع الطلبات الإجراءات المنشورة.', 'Talent programme staff own the routes; answers are cleared when the student asks. It never decides anything on its own: a person reads the reasons and chooses.', 'يملك فريق برامج المواهب المسارات؛ وتُمسح الإجابات حين يطلب الطالب. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Students and applicants, not staff, so it is outside the staff fairness population.', 'للطلاب والمتقدمين لا الموظفين، فهو خارج فئة الإنصاف للموظفين.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 28, 'match', 'options', null, 'non_staff'),
('conversations', 'recommend', 'M18', '/team/conversations', 'F12', 'Career conversation suggestions', 'اقتراحات المحادثة المهنية', 'Suggests actions and courses for the agenda a manager and employee agreed.', 'يقترح إجراءات ودورات لجدول الأعمال الذي اتفق عليه المدير والموظف.', 'Head of Talent and Careers (role card)', 'رئيس المواهب والمسارات المهنية (بطاقة دور)', '[{"key":"conversation_agenda","en":"The agreed conversation agenda, preparation notes and catalogue courses","ar":"جدول المحادثة المتفق عليه وملاحظات التحضير ودورات الكتالوج"},{"key":"training_records","en":"Courses I completed or am enrolled in","ar":"الدورات التي أكملتها أو المسجّل فيها"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m18/conversations.ts#suggestActions']::text[], array['core','important','useful']::text[], 'A short list of actions with reasons; both people agree what goes into the plan.', 'قائمة قصيرة بالإجراءات مع الأسباب؛ ويتفق الطرفان على ما يدخل الخطة.', 'Nothing enters the plan without both people agreeing. It never decides anything on its own: a person reads the reasons and chooses.', 'لا يدخل شيء الخطة دون موافقة الطرفين. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Ranks catalogue content for the agreed agenda only.', 'يرتّب محتوى الكتالوج لجدول الأعمال المتفق عليه فقط.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 29, 'recommend', 'content', null, 'content'),
('passport', 'match', 'M17', '/my/skills', 'F03 · F10 · F11', 'Skills passport strengths', 'نقاط القوة في جواز المهارات', 'Lists my transferable strengths and the roles they are closest to, and the actions a team lead could take on team gaps.', 'يعرض نقاط قوتي القابلة للنقل والأدوار الأقرب إليها، والإجراءات التي يمكن لقائد الفريق اتخاذها لسد فجوات الفريق.', 'Nuclear training academy lead (role card)', 'مسؤول أكاديمية التدريب النووي (بطاقة دور)', '[{"key":"passport_context","en":"My validated skill levels, role requirements and similar roles","ar":"مستويات مهاراتي المعتمدة ومتطلبات الأدوار والأدوار المشابهة"},{"key":"role_competencies","en":"The competency levels each role requires (core, important, useful)","ar":"مستويات الكفاءة التي يتطلبها كل دور (أساسية، مهمة، مفيدة)"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m17/passport.ts#transferableStrengths','src/modules/m17/checkins.ts#teamActions']::text[], array['skills','development','target']::text[], 'Strengths and similar roles with reasons; team actions only for teams of ten or more.', 'نقاط قوة وأدوار مشابهة مع الأسباب؛ وإجراءات الفريق للفرق من عشرة أشخاص فأكثر فقط.', 'I choose what to share; the passport never places anyone. It never decides anything on its own: a person reads the reasons and chooses.', 'أختار ما أشاركه؛ ولا يضع الجواز أحداً في أي موقع. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Only validated or evidenced levels count.', 'تُحتسب المستويات المعتمدة أو المثبتة فقط.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 30, 'match', 'options', null, 'content'),
('accreditation', 'skills', 'M26', '/training/accreditation', 'F29', 'Accreditation evidence suggestions', 'اقتراحات أدلة الاعتماد', 'Suggests which evidence already on file supports each accreditation criterion.', 'يقترح أي الأدلة المتوفرة تدعم كل معيار من معايير الاعتماد.', 'Training quality and accreditation lead (role card)', 'مسؤول جودة التدريب والاعتماد (بطاقة دور)', '[{"key":"accreditation_criteria","en":"Accreditation criteria and the evidence kinds already on file","ar":"معايير الاعتماد وأنواع الأدلة المتوفرة"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m26/accr.ts#suggestFor']::text[], '{}'::text[], 'Suggestions per criterion; the self-evaluation team decides what to submit.', 'اقتراحات لكل معيار؛ ويقرّر فريق التقييم الذاتي ما يُقدَّم.', 'Kafa''a is not an accreditation authority: the accrediting body decides. It never decides anything on its own: a person reads the reasons and chooses.', 'كفاءة ليست جهة اعتماد: الجهة المعتمِدة هي التي تقرّر. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Ranks evidence records, not people.', 'يرتّب سجلات الأدلة لا الأشخاص.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 31, 'rules', 'content', null, 'content')
